1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	};
8	
9	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
10	
11	export type ScenarioResult = { premium: number };
12	
13	export type ScenarioOutcome = { results: ScenarioResult[] };
14	
15	type Item = { type: string };
16	
17	type Scenario = { steps: { items: Item[] }[] };
18	
19	const basePremiumOf = (item: Item): number =>
20	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
21	
22	// Adds the surcharge as a separate term rather than scaling by 1.1, because
23	// `100 * 1.1` is 115.00000000000001 in binary floating point.
24	const withFirstInsuranceSurcharge = (amount: number): number =>
25	  amount + amount * FIRST_INSURANCE_SURCHARGE_RATE;
26	
27	const quotePremium = (items: Item[]): number => {
28	  const basePremium = items.reduce<number>(
29	    (total, item) => total + basePremiumOf(item),
30	    0,
31	  );
32	
33	  return withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
34	};
35	
36	export const runScenario = (scenario: unknown): ScenarioOutcome => {
37	  const { steps } = scenario as Scenario;
38	
39	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
40	
41	  return { results };
42	};
